	private static boolean minusObservesInjectedBindings(TupleExpr subtree, Set<String> injectedNames) {
		if (injectedNames.isEmpty()) {
			return false;
		}
		boolean[] observes = { false };
		subtree.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>(false) {
			@Override
			public void meet(Difference difference) {
				if (observes[0]) {
					return;
				}
				Set<String> assuredByLeft = difference.getLeftArg().getAssuredBindingNames();
				for (String name : difference.getRightArg().getBindingNames()) {
					if (injectedNames.contains(name) && !assuredByLeft.contains(name)) {
						observes[0] = true;
						return;
					}
				}
				super.meet(difference);
			}
		});
		return observes[0];
	}

	private static QueryValueEvaluationStep precompileScopedCondition(EvaluationStrategy strategy, LeftJoin leftJoin,
			QueryEvaluationContext context) {
		QueryValueEvaluationStep condition;
		try {
			condition = scopedOccurrence(strategy.precompile(leftJoin.getCondition(), context), context);
		} catch (QueryEvaluationException e) {
			// A condition that fails to compile can never be true, so the OPTIONAL never matches (as in
			// FilterIterator).
			condition = new QueryValueEvaluationStep.ConstantQueryValueEvaluationStep(BooleanLiteral.FALSE);
		}
		// Like the ordinary OPTIONAL path, the condition only sees the operands' bindings; incoming bindings of other
		// names may come from a sibling row and are out of scope.
		return new ScopedQueryValueEvaluationStep(leftJoin.getBindingNames(), condition);
	}

	private static QueryValueEvaluationStep scopedOccurrence(QueryValueEvaluationStep condition,
			QueryEvaluationContext context) {
		return row -> {
			try (var ignored = context.getBlankNodeAllocationScope().beginSolutionOccurrence(row)) {
				return condition.evaluate(row);
			}
		};
	}

	public LeftJoinQueryEvaluationStep(QueryEvaluationStep right, QueryValueEvaluationStep condition,
			QueryEvaluationStep left, LeftJoin leftJoin, Set<String> optionalVars) {
		this.left = left;
		this.leftJoin = leftJoin;
		// This is used to determine if the left join is well designed.

		Set<String> leftBindingNames = leftJoin.getLeftArg().getBindingNames();

		if (!leftBindingNames.isEmpty()) {
			if (leftBindingNames.containsAll(optionalVars)) {
				optionalVars = Set.of();
			} else {
				for (String leftBindingName : leftBindingNames) {
					if (optionalVars.contains(leftBindingName)) {
						optionalVars = new HashSet<>(optionalVars);
						optionalVars.removeAll(leftBindingNames);
						break;
					}
				}
			}
		}

		this.optionalVars = optionalVars;
		this.rightWithCondition = determineRightEvaluationStep(
				leftJoin,
				right,
				condition,
				leftJoin.getBindingNames());
	}

	@Override
	public CloseableIteration<BindingSet> evaluate(BindingSet bindings) {
		Set<String> problemVars = findProblemVars(bindings);
		if (problemVars == null) {
			leftJoin.setAlgorithm(LeftJoinIterator.class.getSimpleName());
			return LeftJoinIterator.getInstance(left, bindings, rightWithCondition);
		}
		// Filter inherited problem variables from the operands while keeping their own output names visible to the
		// condition.
		leftJoin.setAlgorithm(BadlyDesignedLeftJoinIterator.class.getSimpleName());
		return new BadlyDesignedLeftJoinIterator(left, bindings, problemVars, rightWithCondition);
	}

	private Set<String> findProblemVars(BindingSet bindings) {
		if (optionalVars.isEmpty()) {
			return null;
		}
		if (optionalVars.size() == 1) {
			String name = optionalVars.iterator().next();
			return bindings.hasBinding(name) ? Set.of(name) : null;
		}

		int bindingCount = bindings.size();
		if (bindingCount == 0) {
			return null;
		}
		Set<String> possibleNames = bindings.getBindingNames();
		if (possibleNames.size() == bindingCount) {
			// The names already give the exact domain. Match without reading any of the values.
			return intersect(possibleNames, optionalVars);
		}

		// Possible columns such as SERVICE UNDEF need not belong to the row's binding domain.
		// Walk the row once to avoid scanning the same list or array for each optional variable.
		Set<String> problemVars = null;
		int visited = 0;
		for (Binding binding : bindings) {
			String name = binding.getName();
			if (optionalVars.contains(name)) {
				problemVars = addProblemVar(problemVars, name);
			}
			visited++;
		}
		if (visited < bindingCount) {
			// Some rows have explicit-null bindings that the iterator omits.
			for (String name : optionalVars) {
				if ((problemVars == null || !problemVars.contains(name)) && bindings.hasBinding(name)) {
					problemVars = addProblemVar(problemVars, name);
				}
			}
		}
		return problemVars;
	}

	private static Set<String> intersect(Set<String> first, Set<String> second) {
		if (first.size() > second.size()) {
			Set<String> swap = first;
			first = second;
			second = swap;
		}
		Set<String> problemVars = null;
		for (String name : first) {
			if (second.contains(name)) {
				problemVars = addProblemVar(problemVars, name);
			}
		}
		return problemVars;
	}

	private static Set<String> addProblemVar(Set<String> problemVars, String name) {
		if (problemVars == null) {
			problemVars = new HashSet<>();
		}
		problemVars.add(name);
		return problemVars;
	}

	/**
	 * This function determines the way the right-hand side is evaluated. There are 3 options:
	 * <p>
	 * 1. No join condition: <br>
	 * The right-hand side should just be joined with the left-hand side. No filtering is applied.
	 * </p>
	 * <p>
	 * 2. The join condition can be fully evaluated by the left-hand side:
	 *
	 * <pre>
	 * SELECT * WHERE {
	 * 	?dist a dcat:Distribution .
	 *  ?dist dc:license ?license .
	 *
	 *  OPTIONAL {
	 *     	?a dcat:distribution ?dist.
	 *
	 *      FILTER(?license = <http://wiki.data.gouv.fr/wiki/Licence_Ouverte_/_Open_Licence>)
	 * 	}
	 * }
	 * </pre>
	 *
	 * In this case, pre-filtering can be applied. The right-hand side does not have to evaluated when the join
	 * condition evaluates to false.
	 * </p>
	 * <p>
	 * 3. The join condition needs right-hand side evaluation:
	 *
	 * <pre>
	 * SELECT * WHERE {
	 *  ?dist a dcat:Distribution .
	 *
	 * 	OPTIONAL {
	 *		?a dcat:distribution ?dist .
	 * 		?a dct:language $lang .
	 *
	 * 		FILTER(?lang = eu-lang:ENG)
	 *     	}
	 * }
	 * </pre>
	 *
	 * In this case, the join condition can only be evaluated after the right-hand side is evaluated (post-filtering).
	 * </p>
	 */
	public static QueryEvaluationStep determineRightEvaluationStep(
			LeftJoin join,
			QueryEvaluationStep prepareRightArg,
			QueryValueEvaluationStep joinCondition,
			Set<String> scopeBindingNames) {
		if (joinCondition == null) {
			return prepareRightArg;
		} else if (canEvaluateConditionBasedOnLeftHandSide(join)
				&& QueryEvaluationUtility.canDiscardWithoutEvaluation(join.getRightArg())) {
			// pre-filtering skips right-hand evaluation for rejected left solutions, which is only permitted
			// when the skipped operand cannot raise an observable query-fatal error
			return new PreFilterQueryEvaluationStep(
					prepareRightArg,
					new ScopedQueryValueEvaluationStep(join.getAssuredBindingNames(), joinCondition),
					join);
		} else {
			return new PostFilterQueryEvaluationStep(
					prepareRightArg,
					new ScopedQueryValueEvaluationStep(scopeBindingNames, joinCondition),
					join);
		}
	}

	private static boolean canEvaluateConditionBasedOnLeftHandSide(LeftJoin leftJoin) {
		var varNames = VarNameCollector.process(leftJoin.getCondition());
		return leftJoin.getAssuredBindingNames().containsAll(varNames);
	}
